<?php include "db.php"; if(!isset($_SESSION['user_id'])){header("Location: login.php");exit();} $room_id=(int)($_GET['room_id']??0);$stmt=mysqli_prepare($conn,"SELECT * FROM rooms WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$room_id);mysqli_stmt_execute($stmt);$room=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$room)die("Room type not found. <a href='rooms.php'>Back</a>");$msg="";if(isset($_POST['book'])){$checkin=$_POST['checkin'];$checkout=$_POST['checkout'];$guests=(int)$_POST['guests'];if($checkin<date('Y-m-d')||$checkout<=$checkin||$guests<1){$msg="Choose valid dates and guest count.";}else{$stmt=mysqli_prepare($conn,"SELECT COUNT(*) AS total FROM bookings WHERE room_id=? AND status='Booked' AND checkin < ? AND checkout > ?");mysqli_stmt_bind_param($stmt,"iss",$room_id,$checkout,$checkin);mysqli_stmt_execute($stmt);$count=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt))['total'];if($count >= $room['quantity']){$msg="Sorry, no rooms are available for those dates.";}else{$nights=(strtotime($checkout)-strtotime($checkin))/86400;$total=$nights*$room['price'];$stmt=mysqli_prepare($conn,"INSERT INTO bookings(user_id,room_id,checkin,checkout,guests,total_price,status) VALUES(?,?,?,?,?,?,'Booked')");mysqli_stmt_bind_param($stmt,"iissid",$_SESSION['user_id'],$room_id,$checkin,$checkout,$guests,$total);if(mysqli_stmt_execute($stmt)){header("Location: my_bookings.php?success=1");exit();}else{$msg="Booking failed. Please try again.";}}}} ?>
<!DOCTYPE html><html><head><title>Book Room</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StayEase Hotels</h1><nav><a href="index.php">Home</a><a href="rooms.php">Rooms</a><a href="my_bookings.php">My Bookings</a></nav></header><div class="container"><div class="form-box"><h2>Book: <?php echo htmlspecialchars($room['room_type']); ?></h2><p>Price: ₹<?php echo number_format($room['price'],2); ?> per night</p><?php if($msg)echo '<p class="error">'.htmlspecialchars($msg).'</p>'; ?><form method="post"><label>Check-in date</label><input type="date" name="checkin" min="<?php echo date('Y-m-d'); ?>" required><label>Check-out date</label><input type="date" name="checkout" min="<?php echo date('Y-m-d',strtotime('+1 day')); ?>" required><label>Number of guests</label><input type="number" name="guests" min="1" max="10" value="1" required><button name="book">Confirm Booking</button></form><p><small>Demo project: payment gateway integration is not enabled.</small></p></div></div></body></html>